SELECT     TRUNC(SYSDATE)                                        AS report_da,     wd.HALF_NO                                            AS half_no,     wd.MONTH_NO                                           AS month_no,     wd.WEEK_NO                                            AS week_no,     wd.EOW_DATE                                           AS week_end_date,      p.CURR_454_WEEK                                       AS curr_454_week,     p.CURR_454_MONTH                                      AS curr_454_month,     p.CURR_454_YEAR                                       AS curr_454_year,     p.START_454_MONTH                                     AS month_start_date,     p.END_454_MONTH                                       AS month_end_date,      wd.DEPT                                               AS dept_no,     d.DEPT_NAME                                           AS dept_name,     d.PROFIT_CALC_TYPE                                    AS accounting_method,     CASE d.PROFIT_CALC_TYPE         WHEN 1 THEN 'Cost Method'         WHEN 2 THEN 'Retail Method'     END                                                   AS accounting_method_desc,     wd.CLASS                                              AS class_no,     c.CLASS_NAME                                          AS class_name,     wd.SUBCLASS                                           AS subclass_no,     sc.SUB_NAME                                           AS subclass_name,      wd.LOCATION                                           AS location_id,     wd.LOC_TYPE                                           AS loc_type,     CASE wd.LOC_TYPE         WHEN 'S' THEN 'Store'         WHEN 'W' THEN 'Warehouse'     END                                                   AS loc_type_desc,     CASE wd.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                   AS location_name,     wd.CURRENCY_IND                                       AS currency_ind,      wd.OPN_STK_RETAIL                                     AS open_stock_retail,     wd.OPN_STK_COST                                       AS open_stock_cost,      wd.PURCH_RETAIL                                       AS received_retail,     wd.PURCH_COST                                         AS received_cost,      wd.NET_SALES_RETAIL                                   AS net_sales_retail,     wd.NET_SALES_COST                                     AS net_sales_cost,     wd.SALES_UNITS                                        AS net_sales_units,     wd.NET_SALES_RETAIL_EX_VAT                            AS net_sales_retail_ex_vat,      wd.RETURNS_RETAIL                                     AS returns_retail,     wd.RETURNS_COST                                       AS returns_cost,      wd.TSF_IN_RETAIL                                      AS transfer_in_retail,     wd.TSF_IN_COST                                        AS transfer_in_cost,     wd.TSF_IN_BOOK_RETAIL                                 AS transfer_in_book_retail,     wd.TSF_IN_BOOK_COST                                   AS transfer_in_book_cost,     wd.TSF_OUT_RETAIL                                     AS transfer_out_retail,     wd.TSF_OUT_COST                                       AS transfer_out_cost,     wd.TSF_OUT_BOOK_RETAIL                                AS transfer_out_book_retail,     wd.TSF_OUT_BOOK_COST                                  AS transfer_out_book_cost,      wd.RTV_RETAIL                                         AS rtv_retail,     wd.RTV_COST                                           AS rtv_cost,      wd.PERM_MARKDOWN_RETAIL                               AS perm_markdown_retail,     wd.PROM_MARKDOWN_RETAIL                               AS promo_markdown_retail,     wd.CLEAR_MARKDOWN_RETAIL                              AS clearance_markdown_retail,     wd.MARKDOWN_CAN_RETAIL                                AS markdown_cancel_retail,     NVL(wd.PERM_MARKDOWN_RETAIL, 0)         + NVL(wd.PROM_MARKDOWN_RETAIL, 0)         + NVL(wd.CLEAR_MARKDOWN_RETAIL, 0)               AS total_markdowns_retail,      wd.MARKUP_RETAIL                                      AS markup_retail,     wd.MARKUP_CAN_RETAIL                                  AS markup_cancel_retail,      wd.STOCK_ADJ_RETAIL                                   AS stock_adj_retail,     wd.STOCK_ADJ_COST                                     AS stock_adj_cost,     wd.STOCK_ADJ_COGS_RETAIL                              AS stock_adj_cogs_retail,     wd.STOCK_ADJ_COGS_COST                                AS stock_adj_cogs_cost,     wd.STOCKTAKE_ADJ_RETAIL                               AS stocktake_adj_retail,     wd.STOCKTAKE_ADJ_COST                                 AS stocktake_adj_cost,      wd.FREIGHT_COST                                       AS freight_cost,     wd.EMPL_DISC_RETAIL                                   AS employee_disc_retail,     wd.CASH_DISC_AMT                                      AS cash_disc_retail,     wd.COST_VARIANCE_AMT                                  AS cost_variance,     wd.WORKROOM_AMT                                       AS workroom_cost,     wd.FREIGHT_CLAIM_RETAIL                               AS freight_claim_retail,     wd.FREIGHT_CLAIM_COST                                 AS freight_claim_cost,      wd.DEAL_INCOME_PURCH                                  AS deal_income_purchase,     wd.DEAL_INCOME_SALES                                  AS deal_income_sales,     wd.DEAL_INCOME_ISSUES                                 AS deal_income_issues,     wd.DEAL_COST_ADJUSTMENT                               AS deal_cost_adjustment,     wd.FIXED_DEAL_INCOME                                  AS fixed_deal_income,      wd.RECLASS_IN_RETAIL                                  AS reclass_in_retail,     wd.RECLASS_IN_COST                                    AS reclass_in_cost,     wd.RECLASS_OUT_RETAIL                                 AS reclass_out_retail,     wd.RECLASS_OUT_COST                                   AS reclass_out_cost,      wd.INTERCOMPANY_IN_RETAIL                             AS intercompany_in_retail,     wd.INTERCOMPANY_IN_COST                               AS intercompany_in_cost,     wd.INTERCOMPANY_OUT_RETAIL                            AS intercompany_out_retail,     wd.INTERCOMPANY_OUT_COST                              AS intercompany_out_cost,     wd.INTERCOMPANY_MARKUP                                AS intercompany_markup,     wd.INTERCOMPANY_MARKDOWN                              AS intercompany_markdown,     wd.INTERCOMPANY_MARGIN                                AS intercompany_margin,      wd.CLS_STK_RETAIL                                     AS close_stock_retail,     wd.CLS_STK_COST                                       AS close_stock_cost,      wd.HTD_GAFS_RETAIL                                    AS htd_gafs_retail,     wd.HTD_GAFS_COST                                      AS htd_gafs_cost,      wd.SHRINKAGE_RETAIL                                   AS shrinkage_retail,     wd.SHRINKAGE_COST                                     AS shrinkage_cost,      NVL(wd.NET_SALES_RETAIL, 0)         + NVL(wd.RETURNS_RETAIL, 0)                       AS gross_sales_retail,      NVL(wd.NET_SALES_RETAIL, 0)         - NVL(wd.NET_SALES_COST, 0)                       AS gross_margin_amount,      CASE         WHEN NVL(wd.NET_SALES_RETAIL, 0) > 0         THEN ROUND(              (NVL(wd.NET_SALES_RETAIL, 0) - NVL(wd.NET_SALES_COST, 0))              / wd.NET_SALES_RETAIL * 100, 2)     END                                                   AS gross_margin_pct,      wd.GROSS_MARGIN_AMT                                   AS gross_margin_amt_rds,      NVL(wd.OPN_STK_COST, 0)         + NVL(wd.PURCH_COST, 0)         - NVL(wd.CLS_STK_COST, 0)                        AS cogs_derived,      CASE         WHEN ((NVL(wd.OPN_STK_COST, 0) + NVL(wd.CLS_STK_COST, 0)) / 2) > 0         THEN ROUND(              NVL(wd.NET_SALES_COST, 0)              / ((NVL(wd.OPN_STK_COST, 0) + NVL(wd.CLS_STK_COST, 0)) / 2)              * 52, 2)     END                                                   AS annualised_stock_turn,      (SELECT STD_AV_IND FROM MFCS_RDS.RDS_WV_SYSTEM_OPTIONS      WHERE ROWNUM = 1)                                    AS cost_method_flag,     CASE (SELECT STD_AV_IND FROM MFCS_RDS.RDS_WV_SYSTEM_OPTIONS           WHERE ROWNUM = 1)         WHEN 'A' THEN 'Weighted Average Cost'         WHEN 'S' THEN 'Standard Cost'     END                                                   AS cost_method_desc  FROM     MFCS_RDS.RDS_WV_WEEK_DATA               wd      LEFT JOIN MFCS_RDS.RDS_WV_PERIOD        p    ON  TRUNC(wd.EOW_DATE) = TRUNC(p.VDATE)      JOIN  MFCS_RDS.RDS_WV_DEPS              d    ON  wd.DEPT       = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS             c    ON  wd.DEPT       = c.DEPT                                                  AND wd.CLASS      = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS          sc   ON  wd.DEPT       = sc.DEPT                                                  AND wd.CLASS      = sc.CLASS                                                  AND wd.SUBCLASS   = sc.SUBCLASS      LEFT JOIN MFCS_RDS.RDS_WV_STORE         st   ON  wd.LOCATION   = st.STORE                                                  AND wd.LOC_TYPE   = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH            wh   ON  wd.LOCATION   = wh.WH                                                  AND wd.LOC_TYPE   = 'W'  WHERE     wd.EOW_DATE >= ADD_MONTHS(SYSDATE, -3)  ORDER BY     wd.HALF_NO,     wd.MONTH_NO,     wd.WEEK_NO,     d.DEPT_NAME,     c.CLASS_NAME,     sc.SUB_NAME,     CASE wd.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END